"""Original default ul/list-item geometry and marker computed style, sourced from categoryDefs."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';defs=next(x for x in (r/'docs/replica/source/original.js').read_text().splitlines() if x.startswith('const categoryDefs='));categories=json.loads((r/'artifacts/replica/windows-download/categorysection-cases.json').read_text()) if False else None
script=defs+'''const cases=[];for(const lang of ['ko','en'])for(const width of [438,570])for(const key of ['empty','data','schema','access','objects','trial']){const cat=categoryDefs.find(c=>c.key===key);cases.push({id:`${lang}-${width}-${key}`,lang,width,items:cat?(lang==='ko'?cat.detail:cat.en):[]})}const casesJSON=JSON.stringify(cases);window.cases=cases;for(const c of cases){const root=document.createElement('div');root.className='fixture';root.style.width=c.width+'px';root.dataset.id=c.id;root.innerHTML='<ul class="muted" style="padding-left:20px">'+c.items.map(x=>'<li>'+x+'</li>').join('')+'</ul>';document.getElementById('fixtures').append(root)}
const box=(e,a)=>{const b=e.getBoundingClientRect(),r=a.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}};function read(root){const ul=root.querySelector('ul');return{id:root.dataset.id,...box(ul,root),color:getComputedStyle(ul).color,margin:getComputedStyle(ul).margin,padding:getComputedStyle(ul).padding,items:[...ul.children].map(x=>({text:x.textContent,...box(x,ul),markerSize:getComputedStyle(x,'::marker').fontSize,markerLine:getComputedStyle(x,'::marker').lineHeight,markerColor:getComputedStyle(x,'::marker').color,type:getComputedStyle(x).listStyleType}))};}
document.getElementById('bulletlist-record').onclick=async()=>{await document.fonts.ready;const r=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:[...document.querySelectorAll('.fixture')].map(read),cases})});if(!r.ok)throw Error('Evidence failed');document.getElementById('bulletlist-record').textContent='BulletList recorded'};'''
(o/'bulletlist-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'bulletlist.html').write_text('<!doctype html><meta charset="utf-8"><title>BulletList · original isolation</title><link rel="stylesheet" href="bulletlist-original.css"><style>.fixture{position:absolute;left:30px;top:100px;display:flow-root}.fixture:not(:first-child){visibility:hidden}#bulletlist-record{position:fixed;left:30px;top:20px}</style><button id="bulletlist-record">Record BulletList</button><div id="fixtures"></div><script>'+script+'</script>');print('24 literal source list cases')
